const officialGrid = ({ key, label, guideVersion, sourceUrl, scoreName, maxScore, minimumScore = null, focus, questions, rules = [], documents = [], improvements = [], tieBreaker }) => ({
  key, label, mode: "official-grid", guideVersion, sourceUrl, scoreName, maxScore, minimumScore, focus, questions, rules, documents, improvements, tieBreaker,
});

